from typing import List

def find_max_participants(n: int, k: int, preferences: List[int]) -> int:
    def dfs(node: int, visited: set) -> int:
        if node in visited:
            return 0
        visited.add(node)
        return 1 + dfs(preferences[node - 1], visited)

    total = 0
    for i in range(n):
        if i + 1 not in preferences:
            total += 1
        else:
            cycle = dfs(i + 1, set())
            if cycle <= k:
                total += cycle
                k -= cycle

    return total

