    from collections import defaultdict

    def find_cycle(node, visited, stack):
        visited[node] = True
        stack[node] = True

        next_node = preferences[node] - 1
        if not visited[next_node]:
            cycle_length = find_cycle(next_node, visited, stack)
            if cycle_length != 0:
                return cycle_length + 1
        elif stack[next_node]:
            return 1

        stack[node] = False
        return 0

    visited = [False] * n
    stack = [False] * n
    cycle_lengths = []

    for i in range(n):
        if not visited[i]:
            cycle_length = find_cycle(i, visited, stack)
            if cycle_length > 0:
                cycle_lengths.append(cycle_length)

    cycle_lengths.sort(reverse=True)

    # Fill the bus with the largest cycles first
    total_participants = 0
    for length in cycle_lengths:
        if k >= length:
            total_participants += length
            k -= length
        else:
            break

    # If there are remaining places, fill them with single participants who are not in a cycle
    for i in range(n):
        if total_participants >= k:
            break
        if preferences[i] == i + 1:  # they are not part of any cycle
            total_participants += 1

    return total_participants

