def max_participants(n, k, preferences):
    # Create a graph to represent the relationships
    graph = {i: set() for i in range(1, n+1)}
    for i, pref in enumerate(preferences, 1):
        graph[pref].add(i)

    # Find all strongly connected components (SCCs)
    def dfs(node, visited, stack):
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor, visited, stack)
        stack.append(node)

    def reverse_dfs(node, visited, component):
        visited[node] = True
        component.append(node)
        for neighbor in range(1, n+1):
            if node in graph[neighbor] and not visited[neighbor]:
                reverse_dfs(neighbor, visited, component)

    stack = []
    visited = {i: False for i in range(1, n+1)}
    for node in range(1, n+1):
        if not visited[node]:
            dfs(node, visited, stack)

    visited = {i: False for i in range(1, n+1)}
    sccs = []
    while stack:
        node = stack.pop()
        if not visited[node]:
            component = []
            reverse_dfs(node, visited, component)
            sccs.append(component)

    # Count participants in each SCC
    scc_sizes = [len(scc) for scc in sccs]

    # Calculate the maximum number of participants that can join
    total_participants = sum(min(size, k) for size in scc_sizes)
    return min(total_participants, k)

